    // 感知・連携しない（なげなわで変形中でも、このselectionMaskは無関係に有効なまま）
    selectionMask = null;
    selectionOverlayCanvas = null; // 可視化用オフスクリーンcanvas（マスク変更時に再生成）
    // ----------------------------------------------------

    // 実行環境系
    ENV = {
        // ブラウザがsafari系か
        multiCanvas: false,
        // 画面幅が狭いデバイスか
        isMobileWidth: false,
        // 初回起動か
        isFirstLaunch: false,
    }

    // AXNOS Paint親要素ID
    paintBodyElement;
    // 使用ブラウザ
    browser;

    // 起動オプションで指定される変数
    checkSameBBS;
    restrictDraftCanvasResizing;
    restrictPost;
    expansionTab;
    option_height;
    option_width;

    // GETパラメーター記憶用
    oekaki_id = null; // 基にするお絵カキコの画像id
    oekaki_width;       // （起動時に指定された）キャンバスの幅
    oekaki_height;      // （起動時に指定された）キャンバスの高さ

    // お絵カキコのpng画像が存在するurl
    oekakiURL;
    oekakiTimeout;
    // 下書き機能画像ファイル名
    draftImageFile;
    // 基にしてお絵カキコ用Image
    oekaki_base;

    post_bbs_pageno;    // 投稿する掲示板のurl.pathname
    post_bbs_title;     // 投稿する掲示板のページタイトル
    // セーブデータの刻印となる情報
    oekaki_bbs_pageno = null; // 基にするお絵カキコの掲示板のページ番号（ロード制限の判定に使用）
    oekaki_bbs_title = null; // 基にするお絵カキコの掲示板のページタイトル（ロード制限時のエラーメッセージ用）

    // 許容するキャンバスサイズ
    minWidth;
    minHeight;
    maxWidth;
    maxHeight;

    // 現在のキャンバスサイズ
    x_size;
    y_size;

    // 背景の地色（肌色/白トグル、E-1c）。skinBackgroundColorは肌色の実値を保持
    backgroundColor;
    skinBackgroundColor;

    // 画像の縦横サイズが異なる時のサムネイルのセンタリング用
    ctx_map_shift_x;
    ctx_map_shift_y;
    scale = 100;

    // カメラ座標（ハンドツールでキャンバスを移動させた差分）
    cameraX = 0;
    cameraY = 0;

    // 回転表示角度（度数、[0,360)。あくまで表示の回転であり画像編集ではない）
    rotation = 0;

    // 背景タイルプレビュー表示用
    url_backgroundimage;

    // キャンバス座標
