        if (this.layerObj[idx].mask) return;
        this.layerObj[idx].mask = { enabled: true, image: (0,_layermask_js__WEBPACK_IMPORTED_MODULE_4__.defaultMaskImage)(this.x_size, this.y_size) };
        this.updateCanvas(targetId);
